<script setup lang="ts">
import { computed,ref,watch } from 'vue'
import { useRoute,useRouter } from 'vue-router'
import { request,ApiError } from '../api/client'
import { state,selectProject,notify } from '../store/workbench'
import { relationshipTypes } from '../lib/display'
import type { RecordData } from '../types'
import StatusPill from '../components/StatusPill.vue'
import ProposalDiff from '../components/ProposalDiff.vue'
const route=useRoute(),router=useRouter(),list=ref<RecordData[]>([]),proposal=ref<RecordData|null>(null),diff=ref<RecordData|null>(null),events=ref<RecordData[]>([]),error=ref(''),busy=ref(false),actor=ref(state.actor||'本地维护者'),reason=ref(''),confirmed=ref(false)
const pid=computed(()=>String(route.params.projectId||state.projectId))
let generation=0
async function load(){const token=++generation;try{const items=await request<RecordData[]>(`/operations/proposals?project_id=${pid.value}&limit=200`);if(token!==generation)return;list.value=items;proposal.value=null;diff.value=null;if(route.params.proposalId){const p=await request<RecordData>(`/operations/proposals/${route.params.proposalId}`);if(p.project_id!==pid.value)throw Error('提案不属于当前项目');const d=await request<RecordData>(`/workbench/proposals/${p.id}/diff`),h=await request<RecordData[]>(`/operations/proposals/${p.id}/history`);if(token!==generation)return;proposal.value=p;diff.value=d;events.value=h}error.value='';confirmed.value=false}catch(e){error.value=(e as Error).message}}
watch(()=>[route.params.projectId,route.params.proposalId,state.initialized],async()=>{if(!state.initialized)return;try{if(state.projectId!==pid.value)await selectProject(pid.value);await load()}catch(e){error.value=(e as Error).message}},{immediate:true})
async function review(action:string){if(!proposal.value||busy.value)return;busy.value=true;try{const r=await request<RecordData>(`/operations/proposals/${proposal.value.id}/${action}`,{expected_version:proposal.value.version,actor:actor.value,reason:reason.value});await load();notify(r.proposal.result?.valid===false?'校验未通过，请查看具体错误。':'审核动作已记录。',r.proposal.result?.valid===false?'warning':'success')}catch(e){if(e instanceof ApiError&&e.status===409){await load();error.value='版本或基线已变化，请重新审阅。未自动重试提交。'}else error.value=(e as Error).message}finally{busy.value=false}}
</script>
<template><section class="panel project-panel"><h2>项目变更提案</h2><p>通用知识提案与流程提案均可独立审阅；校验通过后仍需明确确认提交。</p><RouterLink :to="`/projects/${pid}/knowledge`" class="button secondary">返回项目知识</RouterLink><p v-if="error" class="info-box error" role="alert">{{ error }}</p><div class="proposal-list"><RouterLink v-for="p in list" :key="p.id" :to="`/projects/${pid}/proposals/${p.id}`" class="proposal-row"><span>{{ p.title }}</span> <StatusPill :status="p.status"/></RouterLink><p v-if="!list.length">当前项目尚无提案。</p></div><template v-if="proposal"><h3>{{ proposal.title }}</h3><p>提案事件版本 {{ proposal.version }} · <StatusPill :status="proposal.status"/></p><div v-if="diff?.stale" class="info-box warning">原基线已变化，请重新协调后建立新提案。</div><ProposalDiff :diff="diff"/><div v-if="proposal.result?.valid===false" class="info-box warning" role="alert">校验未通过：{{ JSON.stringify(proposal.result.errors) }}</div><form v-if="['pending','validated'].includes(proposal.status)" @submit.prevent="review(proposal.status==='pending'?'validate':'commit')"><label class="field">操作署名<input v-model="actor" required></label><label class="field">审核依据<textarea v-model="reason" required></textarea></label><label class="check-field"><input v-model="confirmed" type="checkbox"><span>我已阅读本次变更内容及依据，确认提交时会写入知识库。</span></label><div class="inline-actions"><button class="button primary" :disabled="busy||!actor.trim()||!reason.trim()||(proposal.status==='validated'&&!confirmed)">{{ proposal.status==='pending'?'校验当前提案':'确认提交当前提案' }}</button><button type="button" class="button danger" :disabled="busy||!actor.trim()||!reason.trim()" @click="review('reject')">拒绝当前提案</button></div></form><details><summary>提案不可变审核历史</summary><pre v-for="event in events" :key="event.version">{{ JSON.stringify(event,null,2) }}</pre></details></template></section></template>
